package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsAny(CharSequence cs, char[] searchChars)
 * Aiming for maximum branch and line coverage.
 */
public class StringUtils_containsAny_TriageGen2Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse(StringUtils.containsAny(null, new char[]{'a'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse(StringUtils.containsAny("", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse(StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_BasicMatch() {
        assertTrue(StringUtils.containsAny("abcde", new char[]{'c', 'z'}));
        assertTrue(StringUtils.containsAny("abcde", new char[]{'e'}));
        assertTrue(StringUtils.containsAny("abcde", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse(StringUtils.containsAny("abcde", new char[]{'x', 'y', 'z'}));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_Match() {
        // U+1F600 (Grinning Face) is represented by surrogate pair: \uD83D\uDE00
        char[] searchChars = new char[]{\uD83D, \uDE00};
        String input = "Hello \uD83D\uDE00 World";
        assertTrue("Should match supplementary character pair", StringUtils.containsAny(input, searchChars));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_PartialMatch_Fail() {
        // Testing the logic: if ch <= MAX_HIGH_SURROGATE and it matches, 
        // but the next char in searchChars doesn't match the next char in cs.

        // cs has \uD83D \uDE01 (Smiling face)
        // searchChars has \uD83D \uDE00 (Grinning face)
        char[] searchChars = new char[]{\uD83D, \uDE00};
        String input = "\uD83D\uDE01"; 

        // The loop finds \uD83D at index 0. 
        // i=0, csLastIndex=1. j=0, searchLastIndex=1.
        // ch (\uD83D) <= MAX_HIGH_SURROGATE is true.
        // searchChars[j+1] (\uDE00) != cs.charAt(i+1) (\uDE01)
        // It should not return true for this specific loop iteration.
        assertFalse(StringUtils.containsAny(input, searchChars));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_Boundary_CS_End() {
        // Testing the branch: i < csLastIndex is false when the high surrogate is the last char in cs
        // (Though a lone surrogate at the end is technically invalid UTF-16, the code must handle it)
        char[] searchChars = new char[]{\uD83D, \uDE00};
        String input = "test\uD83D"; 

        // i=4, csLastIndex=4. i < csLastIndex is false.
        // It falls into the 'else' block (ch is in BMP logic) and returns true.
        assertTrue(StringUtils.containsAny(input, searchChars));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_Boundary_Search_End() {
        // Testing the branch: j < searchLastIndex is false when the high surrogate is the last char in searchChars
        char[] searchChars = new char[]{\uD83D};
        String input = "\uD83D\uDE00";

        // i=0, j=0. searchLastIndex=0. j < searchLastIndex is false.
        // Falls into 'else' block, returns true.
        assertTrue(StringUtils.containsAny(input, searchChars));
    }

    @Test
    public void testContainsAny_BMP_Boundary() {
        // Verify standard characters at boundaries
        assertTrue(StringUtils.containsAny("a", new char[]{'a'}));
        assertFalse(StringUtils.containsAny("a", new char[]{'b'}));
    }
}
